import {parentJob} from './jobs.js?v=5.0.0';
export const playerAttackValue=(job,base,level,attributes,gear=0)=>base+(level-1)*5+(parentJob(job)==='archer'?attributes.DEX*4+Math.floor(attributes.STR/5):attributes.STR*4+Math.floor(attributes.DEX/3))+gear;
export const playerMagicAttackValue=(level,attributes,gear=0)=>6+level*4+attributes.INT*4+gear;
export const GLOBAL_SKILL_COOLDOWN=850;
export const jobSkillCooldownMs=(skill,context={})=>skill.attackCycle?0:skill.cooldown??3600+skill.unlock*120;
export const freecastThreshold=(context={})=>context.reborn&&context.level>=100?540:450;
export function skillCastMs(skill,attributes={},context={}){return Math.round((skill.castMs||0)*Math.max(0,1-Math.sqrt(Math.max(0,(attributes.DEX||0)*2+(attributes.INT||0))/freecastThreshold(context))));}
export const skillActionDelay=(skill,context={})=>skill.attackCycle?Math.max(1000/7,skill.recovery||0,context.speed||1000):GLOBAL_SKILL_COOLDOWN;

export function jobSkillMultiplier(skill,rank=1){const growth=skill.kind==='heal'?.22:['shield','mana'].includes(skill.kind)?.2:.08;return skill.power*(skill.branch==='second'&&['physical','magic'].includes(skill.kind)?1.4:1)*(1+growth*(Math.max(1,rank)-1));}
const displayedCooldown=(s,c)=>jobSkillCooldownMs(s,c)*(1-(c.cooldown||0));
export function jobSkillSpec(skill,rank=1,job='mage',context={}){if(skill.kind==='passive')return {text:'被動技能 · 學習後常駐生效',cooldown:0,percent:0};if(skill.kind==='buff'&&skill.modifiers)return {text:`${skill.desc} · 持續${skill.duration/1000}秒 · CD ${(displayedCooldown(skill,context)/1000).toFixed(1)}秒`,cooldown:displayedCooldown(skill,context),percent:skill.power*100};if(skill.kind==='buff')return {text:`增益 ${(skill.power*100).toFixed(0)}% · ${skill.duration/1000}秒 · CD ${(displayedCooldown(skill,context)/1000).toFixed(1)}秒`,cooldown:displayedCooldown(skill,context),percent:skill.power*100};const multiplier=jobSkillMultiplier(skill,rank),source=skill.source==='holyShield'?'ATK85%＋DEF15%':skill.source==='shield'?'ATK80%＋DEF20%':skill.kind==='magic'||skill.kind==='mana'||skill.kind==='heal'&&!['recover','breathing'].includes(skill.id)?'MATK':skill.kind==='shield'?'最大HP':'ATK',percent=skill.kind==='shield'?Math.min(25,multiplier*10):multiplier*100,verb=skill.kind==='heal'?'治療':skill.kind==='shield'?'護盾':skill.kind==='mana'?'回復SP':'傷害';return {multiplier,source,percent,cooldown:displayedCooldown(skill,context),text:`${verb} ${source} ${Number(percent.toFixed(1))}%${skill.kind==='shield'?'（總護盾上限25%，持續6.5秒）':''} · CD ${(displayedCooldown(skill,context)/1000).toFixed(2)} 秒${skill.attackCycle?` · 攻擊後延遲 ${(skillActionDelay(skill,context)/1000).toFixed(2)} 秒（${skill.recovery?`大型法術最低${(skill.recovery/1000).toFixed(2)}秒；`:""}由ASPD限制，與普攻共用）`:''}${skill.castMs?` · 詠唱 ${(skillCastMs(skill,context.attributes,context)*(context.castFactor||1)/1000).toFixed(2)}秒（INT＋2DEX達${freecastThreshold(context)}無詠唱）`:''}`};}
